CREATE TABLE subject_pack_versions(key TEXT NOT NULL REFERENCES subject_packs(key),pack_version TEXT NOT NULL,name TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('draft','published')),content_json TEXT NOT NULL CHECK(json_valid(content_json)),created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,published_at INTEGER,PRIMARY KEY(key,pack_version));
